const EARTH_MASK_LAND_COUNT = 11389;

const MASK_N = 192;
const LON_MIN = -170;
const LON_MAX = 190;
const LAT_TOP = 80;
const LAT_BOTTOM = -60;

let maskCache: Uint8Array | null = null;

function decodeMask(): Uint8Array {
  const out = new Uint8Array(MASK_N * MASK_N);
  const rows = EARTH_MASK_RLE.replace(/[^0-9a-z|]/g, '').split('|');
  if (rows.length !== MASK_N) throw new Error('Sai số hàng: ' + rows.length);
  let land = 0;
  for (let y = 0; y < MASK_N; y++) {
    const r = rows[y];
    if (r.length % 2 !== 0) throw new Error('Hàng ' + y + ' bị lỗi');
    let x = 0;
    let isLand = 0;
    for (let i = 0; i < r.length; i += 2) {
      const run = parseInt(r.substr(i, 2), 36);
      if (isLand) {
        for (let k = 0; k < run && x + k < MASK_N; k++) out[y * MASK_N + x + k] = 1;
        land += run;
      }
      x += run;
      isLand = isLand ? 0 : 1;
    }
    if (x !== MASK_N) throw new Error('Hàng ' + y + ' sai độ dài: ' + x);
  }
  if (land !== EARTH_MASK_LAND_COUNT) throw new Error('Sai tổng số ô đất: ' + land);
  return out;
}

function fallbackMask(): Uint8Array {
  const out = new Uint8Array(MASK_N * MASK_N);
  for (let y = 0; y < MASK_N; y++) {
    for (let x = 0; x < MASK_N; x++) {
      const nx = x / MASK_N;
      const ny = y / MASK_N;
      const land =
        (nx > 0.10 && nx < 0.32 && ny > 0.12 && ny < 0.82) ||
        (nx > 0.42 && nx < 0.58 && ny > 0.12 && ny < 0.75) ||
        (nx > 0.58 && nx < 0.88 && ny > 0.12 && ny < 0.62) ||
        (nx > 0.72 && nx < 0.90 && ny > 0.62 && ny < 0.85);
      out[y * MASK_N + x] = land ? 1 : 0;
    }
  }
  return out;
}

function getMask(): Uint8Array {
  if (maskCache) return maskCache;
  try {
    maskCache = decodeMask();
  } catch (err) {
    // Dự phòng: dữ liệu bị lỗi thì dùng bản đồ đơn giản, game vẫn chạy
    console.warn('earthMask lỗi, dùng bản đồ dự phòng:', err);
    maskCache = fallbackMask();
  }
  return maskCache;
}

/** Tỉ lệ đất liền (0 đến 1) của ô (x, y) trên bản đồ có kích thước size x size */
export function earthLandRatio(x: number, y: number, size: number): number {
  const mask = getMask();
  const SUB = 3;
  let land = 0;
  for (let sy = 0; sy < SUB; sy++) {
    for (let sx = 0; sx < SUB; sx++) {
      const u = (x + (sx + 0.5) / SUB) / size;
      const v = (y + (sy + 0.5) / SUB) / size;
      const mx = Math.min(MASK_N - 1, Math.floor(u * MASK_N));
      const my = Math.min(MASK_N - 1, Math.floor(v * MASK_N));
      land += mask[my * MASK_N + mx];
    }
  }
  return land / (SUB * SUB);
}

/** Đổi kinh độ, vĩ độ thật sang toạ độ ô (x, y) */
export function lonLatToTile(lon: number, lat: number, size: number): { x: number; y: number } {
  let l = lon;
  if (l < LON_MIN) l += 360;
  const x = Math.floor(((l - LON_MIN) / (LON_MAX - LON_MIN)) * size);
  const y = Math.floor(((LAT_TOP - lat) / (LAT_TOP - LAT_BOTTOM)) * size);
  return {
    x: Math.max(0, Math.min(size - 1, x)),
    y: Math.max(0, Math.min(size - 1, y)),
  };
}
